"use client";
// Client entry points for the livestock actions (generated by scripts/gen-actions.py).
// Each call POSTs to /api/actions/livestock/<name>; implementations live in src/server/actions-impl/livestock.ts.
import { remoteAction } from "@/lib/remote-action";

export const createHerdAction = remoteAction("livestock", "createHerdAction");
export const herdPurchaseAction = remoteAction("livestock", "herdPurchaseAction");
export const herdExpenseAction = remoteAction("livestock", "herdExpenseAction");
export const herdBirthAction = remoteAction("livestock", "herdBirthAction");
export const herdDeathAction = remoteAction("livestock", "herdDeathAction");
export const herdWeighingAction = remoteAction("livestock", "herdWeighingAction");
export const herdSaleAction = remoteAction("livestock", "herdSaleAction");
